            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "confirmed"
            }
          ]
        },
        "code": {
          "text": "Right lateral epicondylitis, chronic and work-aggravated"
        },
        "subject": {
          "reference": "Patient/patient-1"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-1",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-1",
        "status": "final",
        "code": {
          "text": "Right lateral elbow pain"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Intermittent outer right elbow pain for approximately 9–10 months, persisting and worse over the last 2–3 months. Local ache with sharp pain on lifting and gripping; worse when scanning groceries, lifting bags, pouring a kettle, or gripping a steering wheel, especially with the forearm pronated. Improved by rest and ibuprofen as needed. Occasional night pain when rolling onto that side, waking the patient a few times per week. Mild morning stiffness that settles quickly. Subjective reduced grip with occasional dropping of heavier items."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-2",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-2",
        "status": "final",
        "code": {
          "text": "Right elbow trauma and associated symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No trauma, locking, giving way, redness, warmth, or obvious swelling reported."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Blood pressure"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "component": [
